                var THCACHE = null;
                function thresholdsFor(a) {
                    if (!THCACHE)
                        THCACHE = {};
                    if (!THCACHE[a])
                        THCACHE[a] = thresholdsOn(a);
                    return THCACHE[a];
                }

                /* Points above the last threshold this attribute actually cleared. They are
   real rating, spent, buying nothing -- unless they are carrying a ladder
   (a parked attribute on its way up) which the caller knows about. */
                function deadPoints(a, val, cap) {
                    var th = thresholdsFor(a)
                      , last = 0
                      , next = 0;
                    /* No badge reads this attribute at all -- Free Throw is the only one, and
     calling its whole value "dead" would be absurd. It still makes free
     throws. */
                    if (!th.length)
                        return {
                            none: true,
                            dead: 0
                        };
                    for (var i = 0; i < th.length; i++) {
                        if (th[i].v <= val)
                            last = th[i].v;
                        else if (th[i].v <= cap) {
                            next = th[i].v;
                            break;
                        }
                    }
                    /* Below the FIRST threshold nothing is wasted -- those points are on the way
     to it, and the attribute does its own job regardless of badges. Only points
     sitting ABOVE something already cleared are stranded. */
                    if (!last)
                        return {
                            below: true,
                            dead: 0,
                            next: next,
                            gap: next ? next - val : 0
                        };
                    return {
                        dead: Math.max(0, val - last),
                        last: last,
                        next: next,
                        gap: next ? next - val : 0
                    };
                }

                /* \u2500\u2500 PLAY: what the tables cannot tell you \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500
   Every entry here is an opinion about how the game plays, and is shown as one.
   `why` has to be a mechanism, not an assertion -- "it is bad" teaches nothing,
   "you get switch-hunted and cannot contest" is something a player can check
   against their own games. */
                var PLAYBOOK = [{
                    id: 'shortguard',
                    pos: [0, 1],
                    test: function(b) {
                        return b.h <= 74;
                    },
                    head: 'Short guards get hunted',
                    why: 'At ' + '6\u20192\u201d and under you are the switch every offence looks for: ' + 'they will screen until you are on their wing and shoot over you. The ' + 'model adds a second reason \u2014 this frame also carries a smaller ' + 'attribute budget than a 6\u20195\u201d one.'
                }, {
                    id: 'tallguard',
                    pos: [0, 1],
                    test: function(b) {
                        return b.h >= 75 && b.h <= 79;
                    },
                    head: 'This is the guard height people actually play',
                    why: '6\u20193\u201d\u20136\u20197\u201d is the competitive band: tall enough to ' + 'contest and to shoot over a closeout, short enough to keep the ceilings ' + 'that make a guard worth playing.'
                }, {
                    id: 'passacc',
                    attr: 8,
                    test: function(b) {
                        return b.v[8] >= 86 && b.v[8] < 95 && b.pos >= 2;
                    },
                    head: 'Pass Accuracy is parked in an expensive middle',
                    why: '86 is Dimer Gold and 89 is Break Starter Gold \u2014 both good stopping ' + 'points for a big, who passes out of the post rather than running the ' + 'offence. The next thing worth buying is 95 (Dimer HOF), and on a ' + 'non-guard that is a lot of rating for a badge you will rarely trigger.'
                }, {
                    id: 'pgpass',
                    attr: 8,
                    test: function(b) {
                        return b.pos === 0 && b.v[8] >= 86 && b.v[8] < 95;
                    },
                    head: 'A point guard usually wants to finish the Pass Accuracy climb',
                    why: 'You are the primary creator, so Dimer HOF at 95 is the badge you ' + 'actually use. Stopping at 89 is a big-man stopping point \u2014 correct ' + 'for them, short for you.'
                }, {
                    id: 'slow',
                    test: function(b) {
                        return b.v[17] <= b.caps[17] * 0.72;
                    },
                    head: 'This build cannot get back',
                    why: 'Speed and Agility are the cheapest rating on a big, so the allocator ' + 'sells them first and nothing in the badge table defends them. A big ' + 'who cannot run the floor loses possessions no badge gets back.'
                }, {
                    id: 'nodefense',
                    test: function(b) {
                        return b.v[12] < 60 && b.v[11] < 60;
                    },
                    head: 'Nobody will guard anybody',
                    why: 'Both defensive ratings are under 60. Online you are the target on ' + 'every possession, and the offence you bought is played from the bench.'
                }, {
                    id: 'vert70',
                    test: function(b) {
                        return b.v[20] >= 60 && b.v[20] < 70 && b.caps[20] >= 70;
                    },
                    head: 'Vertical 70 is the cheapest thing on this board',
                    why: '70 Vertical is two HOF badges (Crasher, Possession Closer) plus Rise Up ' + 'and Pogo Stick tiers \u2014 a threshold most builds clear by accident and ' + 'yours is sitting just under.'
                }, {
                    id: 'middy',
                    test: function(b) {
                        return b.v[6] > b.v[5] + 6 && b.v[6] >= 80;
                    },
                    head: 'Mid-Range does double duty that Three-Point does not',
                    why: 'Jumpshot bases gate on Three-Point OR Mid-Range, whichever is higher, ' + 'so the higher middy opens far more bases \u2014 and Mid-Range badges come ' + 'with it. Going higher on the middy than the three is the shooting ' + 'method, not a compromise.'
                }];

                /* Everything the build is doing wrong, or notably right, with the reason. */
                function coach(pos, h, w, ws, alloc, vals, caps) {
                    var b = {
                        pos: pos,
                        h: h,
                        w: w,
                        ws: ws,
                        v: vals,
                        alloc: alloc,
                        caps: caps
                    }
                      , out = [];

                    /* DERIVED first -- these are checkable, so they lead. */
                    var used = 0;
                    for (var i = 0; i < 21; i++)
                        used += alloc[i];
                    var budget = heightBudget(h)
                      , bestH = bestHeightFor(pos);
                    if (bestH !== h && heightBudget(bestH) - budget >= 25) {
                        /* The budget is only half the trade. Say what the taller frame is BUYING
       with those points, or this reads as "everyone should be 6'5\"", which is
       false the moment a build needs to protect a rim. */
                        var keep = []
                          , cA = ceilingsFor(h, w, ws)
                          , cB = ceilingsFor(bestH, Math.min(Math.max(w, PB[pos][bestH].wmin), PB[pos][bestH].wmax), bestH + (ws - h));
                        for (var q = 0; q < 21; q++)
                            if (cA[q] - cB[q] >= 6)
                                keep.push([q, cA[q] - cB[q]]);
                        keep.sort(function(x, y) {
                            return y[1] - x[1];
                        });
                        out.push({
                            kind: 'derived',
                            head: 'What this height costs, and what it buys',
                            why: ft(h) + ' fits about <b>' + budget + '</b> attribute points under the 99 ' + 'wall; ' + ft(bestH) + ' fits <b>' + heightBudget(bestH) + '</b>, ' + (heightBudget(bestH) - budget) + ' more. ' + (keep.length ? ('What you are buying with them is reach: ' + keep.slice(0, 3).map(function(x) {
                                return '<b>' + esc(ATTRS[x[0]]) + '</b> +' + x[1];
                            }).join(', ') + ' in ceiling over the shorter frame. Worth it if the build needs ' + 'them; not if it does not.') : 'The shorter frame gives up nothing in ceilings here, so the ' + 'points are close to free.')
                        });
                    }

                    /* dead points: real rating spent on nothing */
                    var waste = [];
                    for (i = 0; i < 21; i++) {
                        if (alloc[i] <= 25)
                            continue;
                        var d = deadPoints(i, alloc[i], caps[i]);
                        /* a parked attribute is climbing a ladder -- not waste */
                        if (d.dead >= 3 && vals[i] <= alloc[i])
                            waste.push({
                                a: i,
                                d: d
                            });
                    }
                    waste.sort(function(x, y) {
                        return y.d.dead - x.d.dead;
                    });
                    if (waste.length)
                        out.push({
                            kind: 'derived',
                            head: 'Points sitting past their last threshold',
                            why: waste.slice(0, 4).map(function(x) {
                                return '<b>' + esc(ATTRS[x.a]) + ' ' + alloc[x.a] + '</b> \u2014 ' + x.d.dead + ' past the ' + x.d.last + ' threshold' + (x.d.next ? (', next is ' + x.d.next) : ', with nothing above it');
                            }).join('. ') + '. Those points still raise the attribute itself, but they ' + 'buy no badge tier \u2014 so unless you are climbing toward the next ' + 'threshold, the rating is cheaper spent elsewhere.'
                        });

                    /* PLAY second, clearly marked */
                    PLAYBOOK.forEach(function(r) {
                        if (r.pos && r.pos.indexOf(pos) < 0)
                            return;
                        var ok = false;
                        try {
                            ok = r.test(b);
                        } catch (e) {
                            ok = false;
                        }
                        if (ok)
                            out.push({
                                kind: 'play',
                                head: r.head,
                                why: r.why
                            });
                    });
                    return out;
                }

                /* \u2500\u2500 THE META, AND THE QUALITY GATE \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500
   Two failures this file exists to prevent, both commercial rather than
   technical:

   1. A BUILD NOBODY PLAYS. The attribute-point budget peaks at 6'5", but the
      two best centres in 2s are a 6'7" popper (1656 points) and a 6'9" inside
      big (1616). Neither is the maximum and it does not matter -- what makes a
      build good is being a coherent role somebody actually runs. An optimiser
      chasing points walks past both.

   2. A BUILD THAT IS INCOHERENT. Maximising a badge score produces a centre
      with 45 Driving Dunk, or a guard who can neither shoot nor finish. Those
      score well and are worthless, and somebody who paid does not come back.

   EVERY PRESET BELOW WAS CHECKED AGAINST THE EXTRACTED MODEL before being
   listed -- how many legal frames hold its floors in their ceilings, and what
   those floors cost in raw rating against the 99.0 wall. `frames` and `raw`
   are measured, not claimed. A community build that did not reproduce would
   have been dropped; all nine that were tested survived, which is consistent
   with games.gg's thresholds matching the engine 10/10 elsewhere in this
   project.                                                                  */

