                        var best = null;
                        for (var a = 0; a < 21; a++) {
                            if (current[a] >= caps[a])
                                continue;
                            var next = current.slice();
                            next[a]++;
                            settle(next, hb, caps);
                            if (overCap(next, caps))
                                continue;
                            var nextOvr = overallOf(next, hb, caps);
                            if (nextOvr > 85)
                                continue;
                            if (!best || ratingOf(next, hb) > ratingOf(best, hb))
                                best = next;
                        }
                        if (!best)
                            return null;
                        current = best;
                        if (overallOf(current, hb, caps) === 85)
                            return current;
